	bool bIsFullyExtended = false;

UE_FORCEINLINE_HINT T TVector<T>::operator|(const TVector<T>& V) const
{
    return X*V.X + Y*V.Y + Z*V.Z;
}

template<typename T>
UE_FORCEINLINE_HINT T TVector<T>::Dot(const TVector<T>& V) const

UE_FORCEINLINE_HINT T TVector<T>::Size() const
{
    return FMath::Sqrt(X*X + Y*Y + Z*Z);
}

template<typename T>
UE_FORCEINLINE_HINT T TVector<T>::Length() const
{
	return Size();
}

template<typename T>
UE_FORCEINLINE_HINT T TVector<T>::SizeSquared() const
{
    return X*X + Y*Y + Z*Z;
}

inline bool TVector<T>::Normalize(T Tolerance)
{
    const T SquareSum = X*X + Y*Y + Z*Z;
    if(SquareSum > Tolerance)
    {
        const T Scale = FMath::InvSqrt(SquareSum);
        X *= Scale; Y *= Scale; Z *= Scale;
        return true;
    }
    return false;
}

template<typename T>

inline TVector<T> TVector<T>::GetSafeNormal(T Tolerance, const TVector<T>& ResultIfZero) const
{
    const T SquareSum = X*X + Y*Y + Z*Z;

    // Not sure if it's safe to add tolerance in there. Might introduce too many errors
    if(SquareSum == 1.f)
    {
        return *this;
    }		
    else if(SquareSum < Tolerance)
    {
        return ResultIfZero;
    }
    const T Scale = (T)FMath::InvSqrt(SquareSum);
    return TVector<T>(X*Scale, Y*Scale, Z*Scale);
}

fn safe_normal(value: DVec3, tolerance: f64) -> DVec3 {
    let squared = value.length_squared();
    if squared == 1.0 {
        value
    } else if squared < tolerance {
        DVec3::ZERO
    } else {
        value / squared.sqrt()

    root: DVec3,
    effector: DVec3,
    pole: DVec3,
    mut upper: f64,
    mut lower: f64,
    stretch: bool,
    stretch_start: f64,
    stretch_max: f64,
) -> (DVec3, DVec3) {
    let delta = effector - root;
    let mut distance = delta.length();
    let direction = if distance < self.solve_near_zero {
        distance = self.solve_near_zero;
        self.basis[0]
    } else {
        safe_normal(delta, self.normalize_squared)
    };
    let pole_delta = pole - root;
    let near_squared = self.solve_near_zero * self.solve_near_zero;
    let bend = if pole_delta.length_squared() < near_squared {
        self.basis[1]
    } else if direction.cross(pole_delta).length_squared() < near_squared {
        let magnitudes = self.basis.map(|axis| direction.dot(axis).abs());
        let basis = if magnitudes[2] > magnitudes[0] && magnitudes[2] > magnitudes[1] {
            self.basis[0]
        } else {
            self.basis[2]
        };
        let first = safe_normal(basis - direction * basis.dot(direction), 1e-8_f32 as f64);
        first.cross(direction) * self.handedness()
    } else {
        let bend = pole_delta - direction * pole_delta.dot(direction);
        normalize(bend, self.normalize_squared).unwrap_or(bend)
    };
    let mut maximum = upper + lower;
    if stretch {
        let range = stretch_max - stretch_start;
        if range > 1e-4 && maximum > self.solve_near_zero {
            let factor = (stretch_max - 1.0)
                * ((distance / maximum - stretch_start) / range).clamp(0.0, 1.0);
            if factor > 1e-4 {
                upper *= 1.0 + factor;
                lower *= 1.0 + factor;
                maximum *= 1.0 + factor;
            }
        }
    }
    if distance >= maximum {
        return (root + upper * direction, root + maximum * direction);
    }
    let denominator = 2.0 * upper * distance;
    let cosine = if denominator != 0.0 {
        (upper * upper + distance * distance - lower * lower) / denominator
    } else {
        0.0
    };
    let perpendicular = upper * cosine.clamp(-1.0, 1.0).acos().sin();
    let squared = upper * upper - perpendicular * perpendicular;
    let mut projected = if squared > 0.0 { squared.sqrt() } else { 0.0 };
    if cosine < 0.0 {
        projected = -projected;
    }
    (
        root + projected * direction + perpendicular * bend,
        effector,
    )
}

